"""Publish native two-channel energy characterization without RMS accuracy claims."""
from pathlib import Path
import datetime,hashlib,json,zipfile
ROOT=Path(__file__).resolve().parents[1];BASE=ROOT/'artifacts/analog_asic'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def rel(p):return p.relative_to(ROOT).as_posix()
def main():
 cell='gf180_two_channel_energy_root_v1';folder=BASE/'layout'/cell;source=ROOT/'scripts/screen_gf180_two_channel_energy_root_nominal.py';rp=BASE/'results'/(cell+'_nominal_src'+sha(source)[:12]+'.json');r=json.loads(rp.read_text());assert r['module_simulation_completed'] and r['monotonic_energy_response_observed']
 old=BASE/'assembly/article_module_catalog_v16.json';cp=BASE/'assembly/article_module_catalog_v17.json';assert not cp.exists();cat=json.loads(old.read_text());assert all(sha(ROOT/n)==h for n,h in cat['sha256'].items())
 qs=[folder/n for n in ['qualification.json','flat_cap_qualification.json','abstract_qualification.json']];q,fq,aq=[json.loads(p.read_text()) for p in qs];assert q['magic_drc_count']==0 and q['lvs_unique'] and q['gds_roundtrip_lvs_unique'] and q['gds_roundtrip_drc_count']==0 and fq['flat_lvs_unique'] and not fq['negative_aggregate_branches'] and aq['physical_ports_and_size_verified']
 for d in [r,fq,aq]:
  for n,h in d['sha256'].items():
   if Path(n).suffix!='.ext':assert sha(ROOT/n)==h,n
 files=[*qs,rp,folder/(cell+'.gds'),folder/(cell+'.lef'),folder/(fq['flat_subcircuit']+'_cap.spice')];entry={'cell':cell,'role':'two_channel_energy_current_sum_root_receiver','dense_resident_leaf':False,'complete_neuron_functionally_accepted':False,'mos_count':14,'native_mim_count':0,'ports':q['ports'],'bbox_um':q['bbox_um'],'module_layout_and_nominal_simulation_artifacts_complete':True,'monotonic_energy_response_observed':True,'complete_RMS_accepted':False,'views':{p.name:rel(p) for p in files},'limitations':r['scope']+' Measured one/two zero-subtracted response ratio0.596 versus ideal RMS0.707; calibration/range unaccepted.'};cat['characterization_assemblies'].append(entry);cat['revision']=17;cat['previous_catalog']=rel(old);cat['sha256'].update({rel(p):sha(p) for p in files});cat['next_physical_modules']=['differential_candidate_minus_adaptation_formatter','analog_triangle_shape_and_amplitude_product','channel_penalty_sum_threshold_clamp','class_current_readout_argmax','graph_wide_control_dense_resident_and_weight_arrays'];cat['next_assembly']='Complete analog adaptation/inhibition/readout support connections, global bin control and dense full25actor hierarchy. Preserve measured storage and energy errors; no accuracy or population5ms acceptance.';cp.write_text(json.dumps(cat,indent=2)+'\n')
 bp=BASE/'results/gf180_two_channel_energy_root_article_boundary.json';assert not bp.exists();audit={'catalog':rel(cp),'modules':18,'characterization_assemblies':10,'cases':r['cases'],'one_to_two_zero_subtracted_response_ratio':r['one_to_two_zero_subtracted_response_ratio'],'monotonic_energy_response_observed':True,'complete_RMS_accepted':False,'limitations':entry['limitations'],'full_chip_layout_complete':False,'original_float_accuracy_accepted':False,'full_5ms_population_service_accepted':False,'sha256':{rel(p):sha(p) for p in [cp,*files,Path(__file__)]}};bp.write_text(json.dumps(audit,indent=2)+'\n')
 docs=[ROOT/'docs'/n for n in ['AGENTS.md','ACTIVE_TASKS.md','ARCHITECTURE.md','DECISIONS.md','RESULTS.md','PROGRESS.md','project_spec.yaml']];stamp=datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%SZ');zp=BASE/'documentation_history'/('project_docs_before_energy_sum_root_'+stamp+'.zip')
 with zipfile.ZipFile(zp,'x',zipfile.ZIP_DEFLATED) as z:
  for p in docs:z.writestr(rel(p),p.read_bytes())
 zp.with_suffix('.json').write_text(json.dumps({'archive_sha256':sha(zp),'files':{rel(p):{'bytes':p.stat().st_size,'sha256':sha(p)} for p in docs}},indent=2)+'\n')
 def write(p,b):
  tmp=p.with_suffix('.tmp');tmp.write_bytes(b);tmp.replace(p)
 def insert(name,text):
  p=ROOT/'docs'/name;b=p.read_bytes();i=b.index(b'\n## ');write(p,b[:i]+text.encode('utf-8')+b[i:])
 insert('RESULTS.md',f'\n## Native energy current sum and root receiver - 2026-10-10\n\n[Two-channel boundary](../{rel(bp)}) records real14MOS parent, full DRC0/LVS and independent GDS reimport, actual LEF and26 nonnegative flat capacitance branches. Three nominal fixtures complete: receiver VSG0.871080/0.975737/1.046600V for zero/one/two active channels; the two-active inputs have opposite signs. ROOT is not voltage-clamped and no behavioral square/sqrt is inside the circuit. Response is monotonic; one/two zero-subtracted ratio0.596271 differs from ideal RMS0.707107. No RMS accuracy/range acceptance. Catalog revision17:18 reusable module sets and10 characterization assemblies.\n\nInhibition selection/charge actuator completed; analog age/amplitude storage completed with failed functional check (unequal age steps,134mV write-release error). Do not hide those errors. Next physical functions: candidate-minus-adaptation differential formatting, triangle shape and amplitude product, channel penalty reduction/threshold clamp, final class-current/readout interface, global control and dense/full layout.\n')
 insert('ARCHITECTURE.md','\n## Analog energy and adaptation interface - 2026-10-10\n\nCandidate energy requires signed (candidate minus current shared adaptation penalty) per channel. Six native MOS form a balanced current-kernel candidate; two kernels now sum at a physical diode-receiver node with receiver width proportional to channel count. Only two-channel nominal characterization is complete; threshold/current-balance offsets and RMS voltage normalization remain unaccepted. Differential formatter, trained clamp and learned-strength product still required.\n\nAnalog adaptation resident prototype stores age and amplitude on separate MIMs, advances age during AGE phase, then SPIKE resets age and overwrites amplitude. Equal pulses give unequal age increments and amplitude has134mV write-release error; it is not calibrated original-float age/amplitude storage. Triangle shaping, inactive/expiry behavior and across-channel sum remain missing. Peer actuator excludes own-spikers using latched flags; RMS-derived decrement programming remains external.\n')
 insert('PROGRESS.md',f'\nAnalog support milestone: peer-inhibition actuator, adaptation-resident prototype and energy-current kernel characterized; two-channel native sum/root parent complete. Catalog revision17:18 module artifact sets/10 assemblies, with storage and RMS precision failures retained. Full chip/accuracy/population5ms incomplete. Exact prior docs: `{rel(zp)}`.\n')
 insert('DECISIONS.md','\n## Continue analog support after nominal storage/energy errors - 2026-10-10\n\nFollow the users layout-first article workflow: preserve measured age-increment nonlinearity, amplitude write-release offset and RMS-ratio error, finish missing analog functions and connected layout before further precision tuning. Module artifact completion is separate from functional/model accuracy acceptance; neither failed storage check nor nominal monotonic energy response accepts the full adaptation/RMS rule. No digital membrane, QAT or trained-model clipping substitution.\n')
 p=ROOT/'docs/ACTIVE_TASKS.md';b=p.read_bytes().replace(b'article_module_catalog_v16.json',b'article_module_catalog_v17.json').replace(b'catalog revision16',b'catalog revision17').replace(b'18 reusable GF180 module artifact sets and9',b'18 reusable GF180 module artifact sets and 10').replace(b'18 reusable GF180 module artifact sets and 9',b'18 reusable GF180 module artifact sets and 10').replace(b'18 reusable physical modules and9',b'18 reusable physical modules and 10').replace(b'18 reusable physical modules and 9',b'18 reusable physical modules and 10').replace(b'18 reusable module artifact sets and9',b'18 reusable module artifact sets and 10').replace(b'contains 18 completed module view/simulation sets and 9',b'contains 18 completed module view/simulation sets and 10');a=b.index(b'| Job status |');z=b.index(b'\n',a);b=b[:a]+b'| Job status | Peer actuator, adaptation storage and energy-kernel nominal artifacts complete; two-channel sum/root assembly characterized; errors retained; next missing analog functions and dense/full assembly |'+b[z:];write(p,b)
 p=ROOT/'docs/project_spec.yaml';b=p.read_bytes();head,tail=b.split(b'\ndocument:',1);head=head.replace(b'article_module_catalog_v16.json',b'article_module_catalog_v17.json').replace(b'gf180_energy_square_kernel_v1_article_boundary.json',bp.name.encode()).replace(b'  live_sessions: [two_channel_energy_root_three_cases_bounded_120s]',b'  live_sessions: []').replace(b'18_modules_9_assemblies_energy_square_cases_complete',b'18_modules_10_assemblies_energy_sum_root_characterized_accuracy_unaccepted');write(p,head+b'\ndocument:'+tail)
 print(json.dumps({'catalog':rel(cp),'boundary':rel(bp),'modules':18,'assemblies':10},indent=2))
if __name__=='__main__':main()
